import json, os, re, subprocess, time, hashlib
from pathlib import Path
from datetime import datetime, timezone
root=Path('/home/vgpnk/Projects/shokunin/mori-shokunin')
boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip().replace('-','')
classes={
'kernel_oom_notice':['MESSAGE_ID=fe6faa94e7774663a0da52717891d8ef'],
'oomd_notice':['MESSAGE_ID=d989611b15e44c9dbf31e3c81256e4ed'],
'coredump_notice':['MESSAGE_ID=fc2e22bc6ee647b6b90729ab34a250b1'],
'segfault_signal11':['MESSAGE_ID=fc2e22bc6ee647b6b90729ab34a250b1','COREDUMP_SIGNAL=11'],
'unit_sigkill_record':['MESSAGE_ID=98e322203f7a4ed290d09fe03c09fe15','EXIT_CODE=killed','EXIT_STATUS=9'],
'unit_failure_record':['MESSAGE_ID=d9b373ed55a64feb8242e02dbe79a49c']}
def query(scope, matches):
    argv=['journalctl','--'+scope,'-b','--no-pager','-o','json','--output-fields=_BOOT_ID,MESSAGE_ID,COREDUMP_SIGNAL,EXIT_CODE,EXIT_STATUS']+matches
    p=subprocess.run(argv,text=True,capture_output=True,timeout=5)
    result={'argv':argv,'exit':p.returncode,'stderr_bytes':len(p.stderr.encode())}
    if p.returncode or p.stderr:
        result['status']='unavailable'; return result
    try:
        rows=[json.loads(line) for line in p.stdout.splitlines() if line.strip()]
        valid=all(isinstance(r,dict) and r.get('_BOOT_ID')==boot and 'MESSAGE' not in r for r in rows)
        for match in matches:
            key,value=match.split('=',1)
            valid=valid and all(str(r.get(key))==value for r in rows)
        if not valid: raise ValueError('shape')
    except (ValueError,TypeError):
        result['status']='unavailable:record-invalid'; return result
    return {**result,'status':'ok','count':len(rows)}
def counts():
    return {scope:{key:query(scope,matches) for key,matches in classes.items()} for scope in ('user','system')}
def census(path):
    argv=['bash',str(path)]; start=time.monotonic()
    p=subprocess.run(argv,cwd=root,env={**os.environ,'MORI_SHOKUNIN_ROOT':'/home/vgpnk/Projects/shokunin'},text=True,capture_output=True,timeout=90)
    return {'argv':argv,'elapsed_s':round(time.monotonic()-start,6),'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()}
baseline=census(root/'.ufo/waves/round-13/frozen/mori-census.sh')
pre=counts(); delivered=census(root/'tools/mori-census.sh'); post=counts()
scoped={}
for scope,state,body in re.findall(r'^SURFACE journal\.(user|system): (\S+) \((.*)\)$',delivered['stdout'],re.M):
    scoped[scope]={'state':state,'tokens':dict(re.findall(r'([a-z0-9_]+)=([^\s;]+)',body))}
checks=[]
for scope in ('user','system'):
    for key in classes:
        a,b=pre[scope][key],post[scope][key]; actual=scoped.get(scope,{}).get('tokens',{}).get(key)
        okay=a['status']==b['status']=='ok' and actual is not None and actual.isdigit() and a['count']<=int(actual)<=b['count']
        checks.append({'scope':scope,'class':key,'before':a.get('count'),'actual':actual,'after':b.get('count'),'matched':okay})
result={'captured_utc':datetime.now(timezone.utc).isoformat(),'boot':boot,'baseline':baseline,'before_queries':pre,'delivered':delivered,'after_queries':post,'comparisons':checks,'matched':sum(c['matched'] for c in checks),'total':len(checks),'before_scoped_rows':len(re.findall(r'^SURFACE journal\.(?:user|system):',baseline['stdout'],re.M)),'after_scoped_rows':len(scoped)}
print(json.dumps(result,indent=2))
